import * as ecs from "@8thwall/ecs";

import { gameData } from "../core/game-data";

import {
  OBJECT_PLACED_EVENT,
} from "./placement-system";

import {
  collectible,
  CollectibleType,
} from "../components/collectible";


// --------------------------------------------------
// Shuffle helper
// --------------------------------------------------

function shuffle<T>(array:T[]):T[] {

  for(let i=array.length-1;i>0;i--){

    const j =
      Math.floor(
        Math.random()*(i+1)
      );

    [
      array[i],
      array[j],
    ] =
    [
      array[j],
      array[i],
    ];

  }

  return array;

}


// --------------------------------------------------
// Available collectible definitions
// --------------------------------------------------

function getItems(schema:any){

  return shuffle([

    {
      prefab:schema.burritoPrefab,
      type:CollectibleType.BURRITO,
      value:10,
    },

    {
      prefab:schema.steakPrefab,
      type:CollectibleType.STEAK,
      value:20,
    },

    {
      prefab:schema.chiliPrefab,
      type:CollectibleType.CHILI,
      value:25,
    },

    {
      prefab:schema.friesPrefab,
      type:CollectibleType.FRIES,
      value:15,
    },

  ]);

}


// --------------------------------------------------
// Component
// --------------------------------------------------

ecs.registerComponent({

  name:"collectible-spawn-system",


  schema:{

    collectibleSpawnContainer:ecs.eid,


    burritoPrefab:ecs.eid,

    steakPrefab:ecs.eid,

    friesPrefab:ecs.eid,

    chiliPrefab:ecs.eid,

  },



  stateMachine:({world,eid,schemaAttribute,defineState})=>{


    defineState("ready")

    .initial()


    .onEnter(()=>{


      console.log(
        "[Collectibles] Component initialized"
      );



      world.events.addListener(

        world.events.globalId,

        OBJECT_PLACED_EVENT,


        ()=>{


          spawnInitialCollectibles(

            world,

            schemaAttribute.get(eid)

          );


        }


      );


    });


  },


});




// --------------------------------------------------
// Initial Spawn
// --------------------------------------------------

function spawnInitialCollectibles(

  world:ecs.World,

  schema:any

){


  if(gameData.collectiblesSpawned)
    return;



  if(!gameData.driveZoneEid)
    return;



  const runtimeContainer =

    world.getInstanceEntity(

      gameData.driveZoneEid,

      schema.collectibleSpawnContainer

    );



  if(!runtimeContainer){

    console.error(
      "[Collectibles] Missing container"
    );

    return;

  }



  const points =

    shuffle(

      [
        ...world.getChildren(
          runtimeContainer
        )
      ]

    );



  const selected =
    points.slice(0,4);



  const items =
    getItems(schema);



  selected.forEach(
    (point,index)=>{


      createCollectible(

        world,

        items[index],

        point

      );


    }

  );



  gameData.collectiblesSpawned =
    true;


}




// --------------------------------------------------
// Replacement Spawn
// --------------------------------------------------

export function spawnReplacementCollectible(

  world:ecs.World

){


  if(!gameData.driveZoneEid)
    return;



  const component =
    findSpawnComponent();



  if(!component)
    return;



  const runtimeContainer =

    world.getInstanceEntity(

      gameData.driveZoneEid,

      component.container

    );



  if(!runtimeContainer)
    return;



  const points =

    shuffle(

      [
        ...world.getChildren(
          runtimeContainer
        )
      ]

    );



  const freePoints =
    points.filter(
      p=>
      !gameData.collectibleEids.includes(p)
    );



  const point =
    freePoints[0] ?? points[0];



  const items =
    getItems(component);



  createCollectible(

    world,

    items[0],

    point

  );


}





// --------------------------------------------------
// Create collectible entity
// --------------------------------------------------

function createCollectible(

  world:ecs.World,

  item:any,

  point:ecs.Eid

){


  if(!item || !item.prefab)
    return;



  const eid =

    world.createEntity(
      item.prefab
    );



  world.getEntity(eid).set(

    collectible,

    {

      type:item.type,

      value:item.value,

      collected:false,

    }

  );



  const position =

    world.transform.getWorldPosition(
      point
    );



  world.transform.setWorldPosition(

    eid,

    {

      x:position.x,

      y:position.y + 0.05,

      z:position.z,

    }

  );



  gameData.collectibleEids.push(
    eid
  );


  console.log(
    "[Collectibles] Spawned",
    eid,
    item.type
  );


}




// --------------------------------------------------
// Temporary storage for component schema
// --------------------------------------------------

let spawnComponent:any = null;


function findSpawnComponent(){

  return spawnComponent;

}
